"""Shared UI shell; original learning content and stable anchors are preserved."""
from pathlib import Path
import re,json,html
ROOT=Path(__file__).resolve().parents[1]
e=html.escape
ICONS={'home':'<path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-7h6v7"/>','original':'<path d="M4 6h7M4 12h5M4 18h7M15 6h5M13 12h7M15 18h5"/><path d="m12 8 3-2-3-2M12 16l-3 2 3 2"/>','poly':'<rect x="4" y="3" width="16" height="18" rx="3"/><path d="M8 8h8M8 12h5M8 16h7"/>','nap':'<path d="M12 5c-3-2-6-2-10-1v15c4-1 7-1 10 1 3-2 6-2 10-1V4c-4-1-7-1-10 1zm0 0v15"/>','search':'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>'}
def icon(k):return '<svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+ICONS[k]+'</svg>'
def themes():return '<select class="theme-picker" aria-label="外观"><option value="system">跟随系统</option><option value="light">浅色</option><option value="dark">深色</option></select>'
def shell(reader):
 links=''.join(f'<a href="index.html#{target}" data-view="{key}"'+(' aria-current="page"' if key==('nap' if reader else 'home') else '')+f'>{icon(key)}<span>{label}</span></a>' for key,target,label in [('home','home','首页'),('original','original-heading','词汇辨析'),('poly','poly-heading','一词多义'),('nap','nap-part','英语阅读')])
 return ('<a class="skip-link" href="#main">跳至主要内容</a><aside class="sidebar"><a class="brand" href="index.html#home"><span class="brand-mark">Aa</span><span>词间<small>VOCABULARY NOTEBOOK</small></span></a><p class="sidebar-label">资料库</p><nav class="primary-nav" aria-label="主导航">'+links+'<button type="button" data-search>'+icon('search')+'<span>搜索</span><kbd>⌘ K</kbd></button></nav><div class="sidebar-foot"><span>让每一个词，更清晰。</span><label>外观'+themes()+'</label></div></aside><div class="topbar glass"><a href="index.html#home" class="mobile-brand">词间 <span>Notebook</span></a><span class="desktop-context">英语词汇 · 私人资料库</span><div><label class="mobile-theme"><span class="sr-only">外观</span>'+themes()+'</label><button type="button" class="search-trigger" aria-label="搜索资料库" data-search>'+icon('search')+'<span>搜索资料库</span><kbd>⌘ K</kbd></button></div></div>')
def search_dialog():return '<dialog id="search-dialog" class="glass" aria-labelledby="search-title"><div class="search-head">'+icon('search')+'<h2 id="search-title" class="sr-only">全站搜索</h2><input id="search" type="search" autocomplete="off" spellcheck="false" placeholder="单词、中文释义、文章…" aria-label="全站搜索" aria-controls="search-results"><button id="search-close" aria-label="关闭搜索">取消</button></div><section id="search-results" aria-label="全站搜索结果"><p role="status" id="search-status">搜索词汇、例句和阅读文章</p><div id="search-groups"></div></section><div class="search-foot">↑ ↓ 选择 · Enter 打开 · Esc 关闭</div></dialog>'
def build():
 catalog=json.loads((ROOT/'dist/vocabulary.json').read_text());poly=json.loads((ROOT/'dist/polysemy.json').read_text());articles=[{'id':'nap',**json.loads((ROOT/'content/nap_article.json').read_text())}]+json.loads((ROOT/'content/reading_articles.json').read_text())
 meta=json.dumps({'articles':[a['id'] for a in articles]});boot=(ROOT/'content/theme.js').read_text()
 def document(title,body,reader=False,context=''):
  return '<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="color-scheme" content="light dark"><meta name="description" content="英语词汇辨析、一词多义与双语阅读资料库"><title>'+e(title)+' · 词间</title><link rel="icon" href="data:,"><script>'+boot+'</script><link rel="stylesheet" href="./search.css"></head><body'+(' class="reader-page"' if reader else '')+'>'+shell(reader)+'<main id="main" tabindex="-1">'+body+'</main>'+search_dialog()+'<script id="site-meta" type="application/json">'+meta+'</script>'+context+'<script src="./interface.js" defer></script><script src="./search.js" defer></script><script src="./'+('reader' if reader else 'pronunciation')+'.js" defer></script></body></html>'
 p=ROOT/'dist/index.html';page=p.read_text();listing=re.search(r'<section id="list">(.*?)</section><section id="nap-part"',page,re.S)[1]
 total_senses=sum(len(x['senses']) for x in poly['entries'])
 cards=''.join(f'<a class="collection-card" href="#{target}" data-view="{key}"><span class="collection-icon">{icon(key)}</span><span class="eyebrow">PART {n:02}</span><h2>{title}</h2><p>{desc}</p><span class="collection-count">{count}<span aria-hidden="true">↗</span></span></a>' for n,key,target,title,desc,count in [(1,'original','original-heading','词汇辨析','在相近的词之间，找到准确的表达。',str(len(catalog['groups']))+' 组辨析'),(2,'poly','poly-heading','一词多义','从常见义到延伸义，读懂词的不同面貌。',str(len(poly['entries']))+' 个单词 · '+str(total_senses)+' 个义项'),(3,'nap','nap-part','英语阅读','在完整的文章里，理解语言的语境。',str(len(articles))+' 篇双语文章')])
 reading_links=[f'<a class="reading-link" href="{a["id"]}.html"><span class="reading-number">{n:02}</span><span><strong lang="en">{e(a["title"])}</strong><small>{e(a.get("titleZh","英语阅读"))} · {len(a["paragraphs"])} 段</small></span><span aria-hidden="true">↗</span></a>' for n,a in enumerate(articles,1)]
 latest=''.join(f'<a href="#{g["id"]}"><span>{e(" / ".join(w["lemma"] for w in catalog["words"] if w["id"] in g["wordIds"]))}</span><span aria-hidden="true">›</span></a>' for g in catalog['groups'][-4:][::-1])
 body='<section id="home"><header class="home-header"><p class="eyebrow">YOUR PERSONAL REFERENCE</p><h1>词语之间，<br><span>读懂更多。</span></h1><p class="home-intro">一本随手翻阅的英语笔记。<br>查清区别，理解词义，然后回到阅读。</p><button type="button" class="home-search" data-search>'+icon('search')+'<span>查一个词，或找一篇文章</span><kbd>⌘ K</kbd></button></header><div class="section-title"><h2>浏览资料库</h2><span>按你的节奏，随时查阅</span></div><div class="collections">'+cards+'</div><div class="home-bottom"><section><div class="section-title"><h2>最近收录的辨析</h2><a href="#original-heading" data-view="original">查看全部</a></div><div class="recent-list">'+latest+'</div></section><section><div class="section-title"><h2>继续探索</h2><span>阅读精选</span></div>'+reading_links[-1]+'</section></div></section>'
 body+='<section id="reference" hidden><div class="reference-head"><h1 id="view-title">词汇辨析</h1><p id="count" role="status"></p></div><div class="reference-tools"><div class="speech-settings"><label for="accent">读音</label><select id="accent"><option value="en-US">美式 · US</option><option value="en-GB">英式 · UK</option></select></div><div><button id="expand">全部展开</button><button id="collapse">全部折叠</button></div></div><p id="speech-status" role="status">使用设备英语语音</p><section id="list">'+listing+'</section></section><section id="nap-part" hidden><header class="page-header"><p class="eyebrow">PART 03 · READING</p><h1>英语阅读</h1><p>慢一点阅读，让语境帮助你理解。</p></header><div class="reading-directory">'+''.join(reading_links)+'</div><p class="reading-hint">点开文章中的英文单词，即可查阅中英释义。</p></section><footer>词间 · 为查阅与阅读而整理</footer>'
 p.write_text(document('英语词汇与阅读',body))
 for a in articles:
  p=ROOT/'dist'/f'{a["id"]}.html';old=p.read_text();body=re.search(r'<main>(.*?)</main>',old,re.S)[1]
  body=body.replace('<a href="index.html#nap-part">← 阅读目录</a>','<a class="back-link" href="index.html#nap-part">← 阅读目录</a>').replace('<div id="nap-text" class="nap-paper">','<div id="nap-text" class="nap-paper" lang="en">')
  jump='<label class="paragraph-picker">段落 <select id="paragraph-jump"><option value="">选择段落</option>'+''.join(f'<option value="{a["id"]}-{letter}">{letter}</option>' for letter in a['paragraphs'])+'</select></label>'
  body=body.replace('<p id="reader-status"',jump+'<p id="reader-status"');context=re.search(r'<script id="reading-context".*?</script>',old,re.S)[0]
  p.write_text(document(a['title'],body,True,context))
 for name in ['interface.js','pronunciation.js']:(ROOT/'dist'/name).write_bytes((ROOT/'content'/name).read_bytes())
 print('Interface:',len(catalog['groups']),'groups,',len(poly['entries']),'words,',len(articles),'readers')
